810	    fn synth_path(rng: &mut u64) -> String {
811	        // 5% NUL, 8% %, 8% \\, 12% '..', 12% '/', remainder lower-ascii.
812	        let len = (lcg_next(rng) % 96 + 2) as usize;
813	        let mut s = String::with_capacity(len);
814	        for _ in 0..len {
815	            let r = (lcg_next(rng) % 100) as u8;
816	            let ch = match r {
817	                0..=4   => '\0',
818	                5..=12  => '%',
819	                13..=20 => '\\',
820	                21..=32 => '.',
821	                33..=44 => '/',
822	                45..=49 => '~',
823	                50..=59 => 'a',
824	                60..=69 => 'b',
825	                70..=79 => '1',
826	                80..=89 => '-',
827	                _       => '_',
828	            };
829	            s.push(ch);
830	        }
831	        s
832	    }
