836	        let mut rng: u64 = 0xCAFE_F00D_DEAD_BEEF; // fixed seed
837	        let mut accepted = 0;
838	        let mut rejected = 0;
839	        let roots = roots();
840	        for _ in 0..10_000 {
841	            let p = synth_path(&mut rng);
842	            // No prefix to bias toward whitelist; let validate find a match
843	            // if any (most won't).
844	            match validate_against(&p, &roots) {
845	                Ok(v) => {
846	                    accepted += 1;
847	                    // Must match a whitelist root exactly.
848	                    assert!(
849	                        roots.contains(&v.root),
850	                        "accepted root '{}' not in whitelist: input={:?}",
851	                        v.root.display(), p
852	                    );
853	                    // Rel must not contain disallowed bytes (validate strips
854	                    // NUL/% rejection before strip_prefix).
855	                    assert!(!v.rel.contains('\0'), "NUL leaked into rel: {:?}", v.rel);
