164	async fn dispatch(mut req: JsonRpcRequest) -> Result<JsonRpcResponse> {
165	    let id = req.id.clone().unwrap_or(Value::Null);
166	    info!("method={} id={}", req.method, id);
167	
168	    // Sequence matters: known-method check FIRST (so unknown methods return
169	    // -32601 Method not found), then schema validation (-32602 Invalid params),
170	    // then execution. This keeps error codes faithful to JSON-RPC 2.0 §5.1.
171	    if !is_known_method(&req.method) {
172	        return Ok(JsonRpcResponse::err(
173	            id,
174	            -32601,
175	            format!("Method not found: {}", req.method),
176	        ));
177	    }
178	
179	    // JSON-RPC 2.0 § 4.1: `params` MAY be omitted. We coerce `null` (the
180	    // serde_json default for a missing field) to `{}` so schemas of shape
181	    // `{type: object, additionalProperties: false}` accept no-arg calls.
182	    if req.params.is_null() {
183	        req.params = Value::Object(serde_json::Map::new());
184	    }
185	
186	    // INV-4: every dispatched call's params are validated against its schema
187	    // before the tool function runs. Schemas are embedded at compile time
188	    // (see schema.rs) so this check cannot be bypassed at runtime.
189	    if let Err(e) = crate::schema::validate(&req.method, &req.params) {
190	        return Ok(JsonRpcResponse::err(id, -32602, format!("Invalid params: {}", e)));
191	    }
