130	#[test]
131	fn shutdown_on_stdin_close() {
132	    let bin = env!("CARGO_BIN_EXE_mcpd");
133	    let mut child = Command::new(bin)
134	        .stdin(Stdio::piped())
135	        .stdout(Stdio::piped())
136	        .stderr(Stdio::null())
137	        .spawn()
138	        .expect("spawn mcpd");
139	    let mut stdin = child.stdin.take().unwrap();
140	    let mut stdout = BufReader::new(child.stdout.take().unwrap());
141	
142	    // One round-trip.
143	    writeln!(stdin, "{}", json!({"jsonrpc":"2.0","method":"tools/list","id":1})).unwrap();
144	    stdin.flush().unwrap();
145	    let mut resp = String::new();
146	    stdout.read_line(&mut resp).unwrap();
147	    assert!(resp.contains("\"jsonrpc\":\"2.0\""));
148	
149	    // Close stdin → mcpd reads EOF → graceful shutdown.
150	    drop(stdin);
151	    let status = child.wait().expect("wait");
152	    assert!(status.success(), "mcpd should exit 0 on stdin EOF, got {:?}", status);
153	}
